typescript.solution:
import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

const VALUES: Record<string, number> = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

function romanToInt(numeral: string): number {
  let total = 0;
  for (let i = 0; i < numeral.length; i++) {
    const value = VALUES[numeral.charAt(i)] ?? 0;
    // Past the last letter, charAt gives "", which has no value, so next is 0.
    const next = VALUES[numeral.charAt(i + 1)] ?? 0;
    total += value < next ? -value : value;
  }
  return total;
}

console.log(romanToInt(input.trim()));
